import json

class InputIterator:
    def __init__(self, source, fail_on_missing=False):
        self.source = source
        self.fail_on_missing = fail_on_missing
        self.iterator = None

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        return cls(data['source'], data.get('fail_on_missing', False))

    def to_json(self):
        return json.dumps({'source': self.source, 'fail_on_missing': self.fail_on_missing})

    def __iter__(self):
        if not self.iterator:
            try:
                if isinstance(self.source, str):
                    with open(self.source, 'r') as file:
                        self.iterator = iter(file.readlines())
                else:
                    self.iterator = iter(self.source)
            except FileNotFoundError:
                if self.fail_on_missing:
                    raise FileNotFoundError(f"Input source '{self.source}' not found")
                self.iterator = iter([])
        return self

    def __next__(self):
        return next(self.iterator)

